import{z as p,x as B,o as t,c,q as r,j as l,D as e,d as o,s,S as E,b as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"压缩映射","description":"","frontmatter":{"title":"压缩映射","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/contraction-mapping.md","filePath":"econ/contraction-mapping.md","lastUpdated":1791063341000}'),d={name:"econ/contraction-mapping.md"};function A(b,a,h,m,u,T){const i=B("Mermaid");return t(),c("div",null,[a[2]||(a[2]=r('<h1 id="压缩映射" tabindex="-1">压缩映射 <a class="header-anchor" href="#压缩映射" aria-label="Permalink to &quot;压缩映射&quot;">​</a></h1><div class="epigraph"><p>距离每次至少按固定比例缩小，完备空间里迭代收敛到唯一不动点，并且与起点无关。</p><footer>—— 据 Stokey, Lucas and Prescott, Recursive Methods in Economic Dynamics, 1989, 第 3 章；Ok, Real Analysis with Economic Applications 整理</footer></div><p>上一课<a href="/econ/comparative-statics">比较静态</a>在方程 \\(F(x,\\theta)=0\\) 的局部光滑枝上读符号。宏观与动态规划问的是另一类对象：值函数、价格函数满足 \\(T(v)=v\\)。缺口不是再微分一次，而是：算子 \\(T\\) 何时有唯一不动点，以及 Picard 迭代何时全局收敛。本课给出 Banach 压缩；Brouwer/Kakutani 管「连续但非压缩」的存在性，不给唯一、不给算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\((X,d)\\) 完备度量空间（后课常用有界连续函数空间 \\(C(K)\\) 配 \\(\\sup\\) 范数，\\(\\mathbb{R}^n\\) 本身也完备）。\\(T:X\\to X\\) 为压缩：存在 \\(\\beta\\in(0,1)\\) 使 \\(d(Tx,Ty)\\le\\beta d(x,y)\\) 对一切 \\(x,y\\) 成立。则 \\(T\\) 有唯一不动点 \\(x^*\\)，\\(T^n x_0\\to x^*\\) 对任意 \\(x_0\\)，误差 \\(\\le \\beta^n d(x_0,Tx_0)/(1-\\beta)\\)。</p><p>Blackwell 充分条件：若 \\(T\\) 单调且有折扣性 \\(T(f+a)\\le Tf+\\beta a\\)，则 \\(T\\) 在 \\(C(K)\\) 上是模 \\(\\beta\\) 的压缩。后课<a href="/econ/bellman-equation">贝尔曼方程</a>的贝尔曼算子在 \\(\\beta\\lt 1\\) 时走这条，不必每次手算 Lipschitz。本课先把压缩本身钉死。</p><p><span class="marginnote">直觉类比：压缩映射像反复「按 90% 缩小复印」一张地图——无论你从哪一角对齐开始，反复缩小后所有内容都挤向同一个点。折扣因子 \\(\\beta\\lt 1\\) 正是复印机的缩放比例：未来被压一次，任何两套猜测的差距就乘一次 \\(\\beta\\)。</span></p><h3 id="压缩不是「迭代几次就差不多」" tabindex="-1">压缩不是「迭代几次就差不多」 <a class="header-anchor" href="#压缩不是「迭代几次就差不多」" aria-label="Permalink to &quot;压缩不是「迭代几次就差不多」&quot;">​</a></h3><p>数值上迭代几次残差变小，可能只是局部收缩或碰巧的阻尼，不是定理。没有全局模 \\(\\beta\\lt 1\\)，可能存在多个不动点，Picard 从不同初值去不同极限，或根本发散。最优增长的贝尔曼算子是压缩；没有折扣的一些搜寻问题、\\(\\beta=1\\) 的平均报酬问题，要换等价范数或别的定理，不能口头称「也是压缩」。</p><p><span class="marginnote">压缩自动连续。连续映射可以不是压缩：单位闭盘上的恒等映射连续，不动点整盘都是，模是 \\(1\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>验证三件事：空间完备、映射把空间送进自身、\\(d(Tx,Ty)\\le\\beta d(x,y)\\)。函数空间上常用 \\(\\sup\\) 距离；加权 \\(\\sup\\) 范数可以把无界状态上的贝尔曼仍收成压缩（Stokey–Lucas–Prescott 的标准技巧）。等价范数改变 \\(\\beta\\)，不改变完备性——有限维所有范数等价，无穷维要选对。</p><p>唯一性来自：两个不动点距离 \\(\\le\\beta\\) 倍自身，故为零。存在性来自：Cauchy 列 \\(x_{n+1}=Tx_n\\) 因几何级数而 Cauchy，完备则收敛，极限必是不动点（\\(T\\) 连续）。后课<a href="/econ/value-function-iteration">值函数迭代</a>就是这条 Picard。</p>',13)),(t(),l(E,null,{default:e(()=>[s(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%AE%8C%E5%A4%87%E7%A9%BA%E9%97%B4%20X%22%5D%20--%3E%20T%5B%22T%20%E4%B8%BA%E5%8E%8B%E7%BC%A9%E6%A8%A1%20beta%22%5D%0A%20%20T%20--%3E%20U%5B%22%E5%94%AF%E4%B8%80%E4%B8%8D%E5%8A%A8%E7%82%B9%20x%20%E6%98%9F%22%5D%0A%20%20T%20--%3E%20P%5B%22Picard%20%E4%BB%8E%E4%BB%BB%E6%84%8F%E7%82%B9%E6%94%B6%E6%95%9B%22%5D%0A%20%20U%20--%3E%20BELL%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%B4%9D%E5%B0%94%E6%9B%BC%E7%AE%97%E5%AD%90%22%5D%0A%20%20P%20--%3E%20VFI%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%80%BC%E5%87%BD%E6%95%B0%E8%BF%AD%E4%BB%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[o("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"每次应用 \\(T\\)，直径按 \\(\\beta\\) 缩小，所以迭代尾巴被几何级数锁住。折扣因子 \\(\\beta\\lt 1\\) 在经济学里恰好是这个模：未来值被压过一次，两套值函数的差距明天最多 \\(\\beta\\) 倍今天。没有折扣，明天的差距可以原样传回今天，压缩失败。",-1)),(t(),l(E,null,{default:e(()=>[s(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X0%5B%22%E5%88%9D%E5%80%BC%20x0%22%5D%20--%3E%20X1%5B%22x1%20%3D%20T%20x0%22%5D%0A%20%20X1%20--%3E%20X2%5B%22x2%20%3D%20T%20x1%22%5D%0A%20%20X2%20--%3E%20FX%5B%22%E4%B8%8D%E5%8A%A8%E7%82%B9%20x*%22%5D%0A%20%20Y0%5B%22%E5%8F%A6%E4%B8%80%E4%B8%AA%E5%88%9D%E5%80%BC%20y0%22%5D%20--%3E%20Y1%5B%22y1%20%3D%20T%20y0%22%5D%0A%20%20Y1%20--%3E%20FX%0A%20%20SH%5B%22%E6%AF%8F%E6%AD%A5%E4%B8%A4%E8%B7%AF%E5%BE%84%E8%B7%9D%E7%A6%BB%E8%87%B3%E5%B0%91%E7%BC%A9%E5%88%B0%20%CE%B2%20%E5%80%8D%22%5D%20--%3E%20UN%5B%22%E6%AE%8A%E9%80%94%E5%90%8C%E5%BD%92%EF%BC%9A%E4%B8%8D%E5%8A%A8%E7%82%B9%E5%94%AF%E4%B8%80%22%5D%0A%20%20FX%20--%3E%20UN%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">数字实例：误差预算 \\(n\\sim\\log\\varepsilon/\\log\\beta\\)。取 \\(\\beta=0.5\\)、想误差小于 \\(1\\%\\)，约 \\(\\log(0.01)/\\log(0.5)\\approx 7\\) 步就够；换 \\(\\beta=0.95\\)，同样精度要约 90 步。折扣越接近 1，定理仍成立，但迭代慢得让人想换算法。</span></p><p>比较静态与压缩可以接力：不动点 \\(x^*(\\theta)\\) 若 \\(T\\) 对 \\(\\theta\\) 连续（或单调），极限继承连续性（或单调）。这比隐函数弱：不要求可微，但要求全局压缩结构。动态规划里值函数对参数的单调，常用这条，而不是去微分欧拉方程。</p><p><span class="marginnote">模 \\(\\beta\\) 同时给出计算预算：要误差小于 \\(\\varepsilon\\)，大约 \\(n\\sim\\log\\varepsilon/\\log\\beta\\) 步。\\(\\beta\\) 接近 \\(1\\) 时迭代很慢，那是后课加速与策略迭代的动机。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证一般完备度量空间的全部点集拓扑，也不把压缩写成数值线性代数的谱半径讲义。非扩张映射（\\(\\beta=1\\)）可以有、可以没有不动点，不在本课强行收。下一课放下唯一性，只问连续函数在紧凸集上是否至少有一个不动点——均衡存在要用那个，因为超额需求通常不是压缩。</p><p><span class="marginnote">常见误区：数值上迭代几轮残差在变小，就断定收敛到唯一解。可能只是局部阻尼或运气：没有全局模 \\(\\beta\\lt 1\\)，从不同初值出发可以停在不同的不动点，甚至发散。定理给的是「对一切初值、以可预告的速度」收敛，这正是它比「看起来在收敛」值钱的地方。</span></p><p>后课默认：折扣贝尔曼算子是压缩；Picard 全局收敛到唯一值函数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完备空间上的压缩有唯一不动点，Picard 全局几何收敛。</li><li>Blackwell 条件让贝尔曼算子直接继承模 \\(\\beta\\)。</li><li>压缩 \\(\\Rightarrow\\) 连续且唯一；连续远远不够压缩。</li><li>\\(\\beta\\) 接近 \\(1\\) 时存在仍在，计算变慢。</li><li>下一课：<a href="/econ/brouwer-fixed-point">Brouwer 不动点</a>。</li><li>出处：Stokey, Lucas and Prescott, <em>Recursive Methods</em> 第 3 章；Ok。</li></ul>',9))])}const _=p(d,[["render",A]]);export{D as __pageData,_ as default};
